fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32> {
    // Pre-allocate the result with the same length as the indices list
    let mut result = Vec::with_capacity(indices.len());
    // For each index in the list, push the corresponding element from `arr`
    for &idx in &indices {
        // According to the problem statement, idx is guaranteed to be in bounds
        result.push(arr[idx]);
    }
    result
}

